import java.util.*;

public class Main {
    static int[] smallestRange(List<List<Integer>> nums) {
        int k = nums.size();
        int[] pointers = new int[k];
        int bestStart = 0, bestEnd = 0, bestWidth = Integer.MAX_VALUE;

        while (true) {
            int curMin = Integer.MAX_VALUE, curMax = Integer.MIN_VALUE, minList = -1;
            for (int i = 0; i < k; i++) {
                int val = nums.get(i).get(pointers[i]);
                if (val < curMin) { curMin = val; minList = i; }
                curMax = Math.max(curMax, val);
            }
            if (curMax - curMin < bestWidth) {
                bestWidth = curMax - curMin;
                bestStart = curMin;
                bestEnd = curMax;
            }
            pointers[minList]++;
            if (pointers[minList] == nums.get(minList).size()) break;
        }
        return new int[]{bestStart, bestEnd};
    }

    public static void main(String[] args) {
        List<List<Integer>> nums1 = Arrays.asList(
            Arrays.asList(4, 10, 15, 24, 26),
            Arrays.asList(0, 9, 12, 20),
            Arrays.asList(5, 18, 22, 30)
        );
        System.out.println(Arrays.toString(smallestRange(nums1)));
    }
}

