import java.util.*;

public class Main {
    static int[] smallestRange(List<List<Integer>> nums) {
        int k = nums.size();
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int curMax = Integer.MIN_VALUE;

        for (int i = 0; i < k; i++) {
            int val = nums.get(i).get(0);
            heap.add(new int[]{val, i, 0});
            curMax = Math.max(curMax, val);
        }

        int bestStart = 0, bestEnd = 0, bestWidth = Integer.MAX_VALUE;

        while (true) {
            int[] top = heap.poll();
            int val = top[0], listIdx = top[1], elemIdx = top[2];
            if (curMax - val < bestWidth) {
                bestWidth = curMax - val;
                bestStart = val;
                bestEnd = curMax;
            }

            elemIdx++;
            if (elemIdx == nums.get(listIdx).size()) break;

            int nextVal = nums.get(listIdx).get(elemIdx);
            curMax = Math.max(curMax, nextVal);
            heap.add(new int[]{nextVal, listIdx, elemIdx});
        }
        return new int[]{bestStart, bestEnd};
    }

    public static void main(String[] args) {
        List<List<Integer>> nums1 = Arrays.asList(
            Arrays.asList(4, 10, 15, 24, 26),
            Arrays.asList(0, 9, 12, 20),
            Arrays.asList(5, 18, 22, 30)
        );
        System.out.println(Arrays.toString(smallestRange(nums1)));
    }
}

