#include <bits/stdc++.h>
using namespace std;

vector<int> smallestRange(vector<vector<int>>& nums) {
    int k = nums.size();
    using T = tuple<int,int,int>;
    priority_queue<T, vector<T>, greater<T>> heap;
    int curMax = INT_MIN;

    for (int i = 0; i < k; i++) {
        heap.push({nums[i][0], i, 0});
        curMax = max(curMax, nums[i][0]);
    }

    int bestStart = 0, bestEnd = 0, bestWidth = INT_MAX;

    while (true) {
        auto [val, listIdx, elemIdx] = heap.top(); heap.pop();
        if (curMax - val < bestWidth) {
            bestWidth = curMax - val;
            bestStart = val;
            bestEnd = curMax;
        }

        elemIdx++;
        if (elemIdx == (int)nums[listIdx].size()) break;

        int nextVal = nums[listIdx][elemIdx];
        curMax = max(curMax, nextVal);
        heap.push({nextVal, listIdx, elemIdx});
    }
    return {bestStart, bestEnd};
}

int main() {
    vector<vector<int>> nums1 = {{4, 10, 15, 24, 26}, {0, 9, 12, 20}, {5, 18, 22, 30}};
    auto r1 = smallestRange(nums1);
    cout << "[" << r1[0] << "," << r1[1] << "]" << endl;
    return 0;
}
